def transform(grid):
    H=len(grid); W=len(grid[0]); seen=set(); objs=[]
    for r in range(H):
        for c in range(W):
            v=grid[r][c]
            if v and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        z=(x+dx,y+dy)
                        if 0<=z[0]<H and 0<=z[1]<W and grid[z[0]][z[1]]==v and z not in seen:
                            seen.add(z); stack.append(z)
                r0=min(x for x,y in cells); c0=min(y for x,y in cells)
                objs.append((c0,v,[(x-r0,y-c0) for x,y in cells],max(x for x,y in cells)-r0+1,max(y for x,y in cells)-c0+1))
    objs.sort(key=lambda o:o[0]); out=[[0]*W for _ in range(H)]; r=c=0
    for i,(_,v,cells,h,w) in enumerate(objs):
        if i: r+=prevh-1; c+=prevw-1
        for x,y in cells:
            if r+x<H and c+y<W: out[r+x][c+y]=v
        prevh,prevw=h,w
    return out
